package net.officefloor.hq.app.pool;

import java.util.List;

/** A pool as the screen shows it: its name, its members, the total of their shares (a retired member's counting as
 *  0.00) and whether that total is exactly 100.00. */
public record PoolResponse(long id, String name, String totalShare, boolean balanced, List<Member> members) {

    /** A member: the person, their name and their share. */
    public record Member(long personId, String name, String share) {
    }
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** The sheet's pools, in the order they were added, each with its members in the order they were added. A member
 *  with a retirement date set (whatever the date) counts as 0.00 toward the pool's total. */
public class RespondWithPools {
    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    public void respond(@Val Sheet sheet, PoolRepository pools, PoolMemberRepository members, PersonRepository people,
            ObjectResponse<List<PoolResponse>> response) {
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheet.getId()).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        List<PoolResponse> out = new ArrayList<>();
        for (Pool pool : pools.findBySheetIdOrderByIdAsc(sheet.getId())) {
            BigDecimal total = BigDecimal.ZERO.setScale(2);
            List<PoolResponse.Member> shown = new ArrayList<>();
            for (PoolMember member : members.findByPoolIdOrderByIdAsc(pool.getId())) {
                Person person = byId.get(member.getPersonId());
                if (person == null) continue;
                if (person.getRetiredFrom() == null) total = total.add(member.getShare());
                shown.add(new PoolResponse.Member(person.getId(), person.getName(),
                        member.getShare().setScale(2).toPlainString()));
            }
            out.add(new PoolResponse(pool.getId(), pool.getName(), total.toPlainString(),
                    total.compareTo(HUNDRED) == 0, shown));
        }
        response.send(out);
    }
}
package net.officefloor.hq.app.setting;

/** The settings form as submitted: the clerk limit (blank: no limit), the floor (blank: 1.00) and the terms in
 *  days (blank: 14) and the late percent
 *  (blank: 0.00) and the policy date (YYYY-MM-DD; blank: the sheet's today) and the period numbering from (YYYY-MM-DD; blank: off) and the terms of grades A, B and C in days (blank: the sheet's terms) and the cap (blank: none) and the proof threshold (blank: none); and the permission matrix entries for open, settle, void, reassign, close and reopen
 *  (comma separated roles; blank: the standing rule); and the grace days (a whole number of days; blank: off; not dated); and the note threshold (blank: none); and the entry date (YYYY-MM-DD; blank: off; not dated); and the grace days of grades A, B and C (blank: none); and the proof thresholds of grades A, B and C (blank: none — the sheet's applies); a key left out (null) is not changed.
 *  Each setting that carries a figure has its from-date (YYYY-MM-DD; blank or left out: the sheet's today): it is
